from __future__ import annotations

from state_model import Order, copy_order


TERMINAL_STATES = {"delivered", "canceled"}

VALID_TRANSITIONS = {
    "created": {"payment_received", "cancel"},
    "paid": {"warehouse_packed", "cancel"},
    "packed": {"ship", "cancel"},
    "shipped": {"deliver"},
    "delivered": set(),
    "canceled": set(),
}


def _is_transition_allowed(state: str, event: str) -> bool:
    return event in VALID_TRANSITIONS.get(state, set())


def apply_event(order: Order, event: str, metadata: dict | None = None) -> dict:
    metadata = metadata or {}

    if not _is_transition_allowed(order.state, event):
        return {"ok": False, "reason": "invalid_transition", "order": order}

    if order.state in TERMINAL_STATES:
        return {"ok": False, "reason": "terminal_state", "order": order}

    if event == "payment_received":
        updated = copy_order(order, state="paid", payment_confirmed=True)
        return {"ok": True, "reason": "state_changed", "order": updated}

    if event == "warehouse_packed":
        updated = copy_order(order, state="packed", packed_at_warehouse=True)
        return {"ok": True, "reason": "state_changed", "order": updated}

    if event == "ship":
        tracking_id = metadata.get("tracking_id")
        if not isinstance(tracking_id, str) or not tracking_id.strip():
            return {"ok": False, "reason": "missing_tracking_id", "order": order}
        updated = copy_order(order, state="shipped", tracking_id=tracking_id.strip())
        return {"ok": True, "reason": "state_changed", "order": updated}

    if event == "deliver":
        delivered_at = metadata.get("delivered_at")
        if not isinstance(delivered_at, str) or not delivered_at.strip():
            return {"ok": False, "reason": "missing_delivery_timestamp", "order": order}
        updated = copy_order(order, state="delivered", delivered_at=delivered_at.strip())
        return {"ok": True, "reason": "state_changed", "order": updated}

    if event == "cancel":
        updated = copy_order(order, state="canceled")
        return {"ok": True, "reason": "state_changed", "order": updated}

    return {"ok": False, "reason": "unknown_event", "order": order}

